// Generated by Sabine from the app's bridge commands and events. Run `sabine bindings` after changing them.

import { invoke, listen, type CallOptions } from "@lantharos/sabine";

export const commands = {
	addBoard: (params: {
		name: string,
	}, options?: CallOptions) => invoke<Library>("add_board", params, options),
	addSounds: (params: {
		board: number,
		paths: string[],
	}, options?: CallOptions) => invoke<AddResult>("add_sounds", params, options),
	appState: (options?: CallOptions) => invoke<AppState>("app_state", {}, options),
	choosePicture: (params: {
		sound: number,
		title: string,
		filter: string,
	}, options?: CallOptions) => invoke<Library>("choose_picture", params, options),
	chooseSounds: (params: {
		title: string,
		filter: string,
	}, options?: CallOptions) => invoke<string[]>("choose_sounds", params, options),
	configureHotkeys: (options?: CallOptions) => invoke<null>("configure_hotkeys", {}, options),
	exportBoard: (params: {
		board: number,
		name: string,
		title: string,
	}, options?: CallOptions) => invoke<null>("export_board", params, options),
	importBoard: (params: {
		title: string,
		filter: string,
	}, options?: CallOptions) => invoke<Library>("import_board", params, options),
	press: (params: {
		sound: number,
		preview: boolean,
	}, options?: CallOptions) => invoke<null>("press", params, options),
	release: (params: {
		sound: number,
	}, options?: CallOptions) => invoke<null>("release", params, options),
	removeBoard: (params: {
		board: number,
	}, options?: CallOptions) => invoke<Library>("remove_board", params, options),
	removeSound: (params: {
		sound: number,
	}, options?: CallOptions) => invoke<Library>("remove_sound", params, options),
	renameBoard: (params: {
		board: number,
		name: string,
	}, options?: CallOptions) => invoke<Library>("rename_board", params, options),
	reorderSounds: (params: {
		board: number,
		sounds: number[],
	}, options?: CallOptions) => invoke<Library>("reorder_sounds", params, options),
	setKeepRunning: (params: {
		enabled: boolean,
	}, options?: CallOptions) => invoke<null>("set_keep_running", params, options),
	setMix: (params: {
		microphone: string | null,
		microphoneLevel: number,
		microphoneMuted: boolean,
		monitorLevel: number,
		monitorOn: boolean,
	}, options?: CallOptions) => invoke<null>("set_mix", params, options),
	setUseAsDefault: (params: {
		enabled: boolean,
	}, options?: CallOptions) => invoke<null>("set_use_as_default", params, options),
	soundPeaks: (params: {
		sound: number,
		buckets: number,
	}, options?: CallOptions) => invoke<number[]>("sound_peaks", params, options),
	stopAll: (options?: CallOptions) => invoke<null>("stop_all", {}, options),
	updateSound: (params: {
		id: number,
		name: string,
		file: string,
		frames: number,
		look: Look,
		color: string,
		level: number,
		trimStart: number,
		trimEnd: number,
		looping: boolean,
		stopOthers: boolean,
		trigger: Trigger,
	}, options?: CallOptions) => invoke<Library>("update_sound", params, options),
};

export const events = {
	appearanceCorners: (callback: (payload: Corners) => void) => listen<Corners>("appearance.corners", callback),
	appearanceMotion: (callback: (payload: Motion) => void) => listen<Motion>("appearance.motion", callback),
	appearanceTypography: (callback: (payload: Typography) => void) => listen<Typography>("appearance.typography", callback),
	kestrelPalette: (callback: (payload: Palette) => void) => listen<Palette>("kestrel.palette", callback),
	soundboardMeters: (callback: (payload: Meters) => void) => listen<Meters>("soundboard.meters", callback),
	soundboardStatus: (callback: (payload: Status) => void) => listen<Status>("soundboard.status", callback),
	soundboardTriggers: (callback: (payload: Hotkey[]) => void) => listen<Hotkey[]>("soundboard.triggers", callback),
};

export type AddResult = {
	library: Library,
	failed: string[],
};

export type AppIconStyle = "default" | "tinted" | "clear";

export type AppIcons = {
	style: AppIconStyle,
	glyphs: string,
	tinted: IconPaint,
	clear: IconPaint,
};

export type AppState = {
	library: Library,
	settings: Settings,
	status: Status,
	triggers: Hotkey[],
	hotkeysAvailable: boolean,
	soundsFolder: string,
} & Appearance;

export type Appearance = {
	palette: Palette | null,
	typography: Typography,
	motion: Motion,
	corners: Corners,
	locale: Locale,
};

export type Board = {
	id: number,
	name: string,
	sounds: Sound[],
};

export type Corners = "rounded" | "square";

export type Hotkey = {
	id: string,
	keys: string | null,
};

export type IconPaint = {
	plate: string,
	ink: string,
	shade: string,
	rim: number,
};

export type Library = {
	boards: Board[],
};

export type Locale = {
	languages: string[],
	formats: string,
	fixed: boolean,
};

export type Look = { kind: "plain" } | { kind: "emoji"; value: string } | { kind: "icon"; value: string } | { kind: "picture"; value: string };

export type Meters = {
	voice: number,
	output: number,
};

export type Microphone = {
	name: string,
	description: string,
};

export type Mix = {
	microphone: string | null,
	microphoneLevel: number,
	microphoneMuted: boolean,
	monitorLevel: number,
	monitorOn: boolean,
};

export type Motion = "full" | "reduced" | "off";

export type Palette = {
	accent: string,
	wallpaperAccent: string,
	pureBlack: boolean,
	colors: SchemeColors,
	terminal: SchemeColors,
	appIcons: AppIcons,
	taskbar: import("@luft/ui").TaskbarLooks,
};

export type SchemeColors = {
	light: { [key in string]: string },
	dark: { [key in string]: string },
};

export type Settings = {
	mix: Mix,
	keepRunning: boolean,
	useAsDefault: boolean,
	defaultBefore: string | null,
};

export type Sound = {
	id: number,
	name: string,
	file: string,
	frames: number,
	look: Look,
	color: string,
	level: number,
	trimStart: number,
	trimEnd: number,
	looping: boolean,
	stopOthers: boolean,
	trigger: Trigger,
};

export type Status = {
	connected: boolean,
	listeners: number,
	microphones: Microphone[],
	passing: string | null,
	defaultInput: string | null,
	playing: number[],
};

export type Trigger = "press" | "hold";

export type Typography = {
	interface: string | null,
	monospace: string | null,
	textScale: number,
};
